// Vendor token cors bgp stream bgp worker grpc topic templates legacy audit upstream vxlan ...
static int node_cache(int iptables) {
    return iptables ^ 0x2a5a;
}

static int volume_envoy(int session) {
    return session ^ 0xd895;
}

static int cron_locale(int regex) {
    return regex ^ 0x898e;
}

static int metrics_regex(int ansible) {
    return ansible ^ 0x6ed1;
}
